import {readFileSync} from 'node:fs';
import vm from 'node:vm';
import assert from 'node:assert/strict';
import test from 'node:test';
const ctx=vm.createContext({});vm.runInContext(readFileSync(new URL('./model.js',import.meta.url),'utf8'),ctx);const M=ctx.MenuModel;
test('missing price blocks; zero is valid',()=>{const s=M.create();assert.equal(M.issues(s).blockers.length,1);s.items[5].price=0;assert.equal(M.issues(s).blockers.length,0)});
test('pagination excludes unchecked items and obeys capacity',()=>{const s=M.create();assert.equal(M.pages(s).length,3);s.items[0].included=false;s.density=6;assert.equal(M.pages(s).length,2);assert.equal(M.pages(s)[0].items.length,6)});
test('preflight requires explicit warning and missing image decisions',()=>{const s=M.create();s.step=4;s.checked=true;s.items[5].price=30;assert.equal(M.canContinue(s),false);s.noImage=true;s.warnings=true;assert.equal(M.canContinue(s),true)});
test('print output uses physical dimensions',()=>{const s=M.create();s.unit='mm';s.width=210;s.height=297;s.dpi=300;assert.equal(M.size(s).width,2480);assert.equal(M.size(s).height,3508)});
test('generation requires an up-to-date inspection and explicit material decision',()=>{const s=M.create();s.items[5].price=36;s.noImage=true;s.warnings=true;assert.equal(M.canGenerate(s),false);s.checked=true;assert.equal(M.canGenerate(s),true);s.items[5].price=null;assert.equal(M.canGenerate(s),false)});
test('rendered price preserves cents rather than rounding commercial facts',()=>{ctx.window=ctx;vm.runInContext(readFileSync(new URL('./menu-renderer.js',import.meta.url),'utf8'),ctx);const s=M.create();s.items[0].price=48.5;const svg=ctx.MenuRenderer.svg(s,M.pages(s)[0]);assert.ok(svg.includes('¥ 48.50'));});
test('intent is independent of products, but material selection is required',()=>{const s=M.create();s.items=[];s.step=2;assert.equal(M.canContinue(s),true);s.step=3;assert.equal(M.canContinue(s),false)});
test('legacy workflow migration preserves content and maps advanced drafts',()=>{const s=M.create();delete s.workflowVersion;s.step=4;s.maxStep=8;const data=JSON.stringify(s.items);M.migrateWorkflow(s);assert.equal(s.step,2);assert.equal(s.maxStep,8);assert.equal(JSON.stringify(s.items),data);assert.equal(s.workflowVersion,2);M.migrateWorkflow(s);assert.equal(s.step,2)});
test('early legacy drafts revisit page requirements without losing selections',()=>{const s=M.create();delete s.workflowVersion;s.step=3;s.maxStep=3;s.items[0].included=false;M.migrateWorkflow(s);assert.equal(s.step,2);assert.equal(s.maxStep,2);assert.equal(s.items[0].included,false)});
test('old iPad drafts migrate once to landscape without losing materials',()=>{for(const [id,next,w,h] of [['ipad-mini-2','ipad-mini-6',2266,1488],['ipad-8','ipad-8',2160,1620],['ipad-9','ipad-9',2160,1620]]){const s=M.create();delete s.devicePresetsVersion;s.profile=id;s.reference={image:'fixture'};const items=JSON.stringify(s.items);assert.equal(M.migrateDevicePresets(s),true);assert.equal(s.profile,next);assert.equal(s.width,w);assert.equal(s.height,h);assert.equal(s.reference.image,'fixture');assert.equal(JSON.stringify(s.items),items);[s.width,s.height]=[s.height,s.width];assert.equal(M.migrateDevicePresets(s),false);assert.equal(s.width,h);}});
test('device migration preserves unrelated custom sizes',()=>{const s=M.create();delete s.devicePresetsVersion;s.profile='custom';s.width=1234;s.height=2345;assert.equal(M.migrateDevicePresets(s),false);assert.equal(s.width,1234);assert.equal(s.height,2345);});
test('expanded intent defaults preserve old choices and work before product selection',()=>{const s=M.create();s.goal='快速选择';s.density=6;s.items=[];M.ensureIntent(s);assert.equal(s.goal,'快速选择');assert.equal(s.density,6);assert.equal(s.readingScene,'桌面平板近看');assert.match(M.intentSummary(s),/快速选择/);assert.match(M.intentSummary(s),/每页最多 6 道/);s.intentNotes='价格醒目';M.ensureIntent(s);assert.match(M.intentSummary(s),/价格醒目/);assert.equal(s.showBrand,true);});
test('brand colors are optional and strict policy requires a primary color',()=>{const s=M.create();M.ensureBrand(s);assert.equal(M.brandIssue(s),'');s.brandMaterials.policy='strict';assert.match(M.brandIssue(s),/主色/);s.step=3;assert.equal(M.canContinue(s),false);s.brandMaterials.primary='#123456';assert.equal(M.brandIssue(s),'');assert.equal(M.canContinue(s),true);});
test('brand palette policies are deterministic without mutating reference colors',()=>{const s=M.create(),base={bg:'#ffffff',ink:'#111111',accent:'#aa0000',muted:'#777777',card:'#eeeeee',line:'#dddddd'};Object.assign(M.ensureBrand(s),{primary:'#123456',secondary:'#fafafa',accent:'#654321'});assert.equal(M.brandPalette(s,base).ink,'#123456');assert.equal(M.brandPalette(s,base).bg,'#ffffff');s.brandMaterials.policy='strict';assert.equal(M.brandPalette(s,base).bg,'#fafafa');s.brandMaterials.policy='reference';assert.equal(M.brandPalette(s,base).ink,'#111111');assert.equal(base.ink,'#111111');});
